int n ; 
char a [9][9] ; 
int cross1 [maxn] , cross2 [maxn] , column [maxn] ; 
int res = 0 ; 

void backtrack ( int pos ) 
{
    if ( pos > n ) 
    {
        res ++ ; return ; 
    }
    for ( int i = 1 ; i <= n ; i ++ ) 
    {
        if ( column [i] || cross1 [pos+i] || cross2 [pos-i+8] || a [pos][i] == '*' ) continue ; 
        column [i] = cross1 [pos+i] = cross2 [pos-i+8] = true ; 
        backtrack (pos+1) ; 
        column [i] = cross1 [pos+i] = cross2 [pos-i+8] = false ; 
    }
}
signed main () 
{
    ios_base::sync_with_stdio(0); 
    cin.tie(0);cout.tie(0); 
    n = 8 ; 
    for ( int i = 1 ; i <= n ; i ++ ) for ( int j = 1 ; j <= n ; j ++ ) cin >> a [i][j] ; 
    backtrack (1) ; 
    cout << res ; 
    return 0;
}
